// Picture — Gtk.Picture
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles picture with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"
import type { ContentFit } from "@/lib/enums"

export interface PictureProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** utf8, from Gtk.Picture */
  alternativeText?: string

  /** gboolean, from Gtk.Picture */
  canShrink?: boolean

  /** ContentFit, from Gtk.Picture */
  contentFit?: ContentFit

  /** Gio.File, from Gtk.Picture */
  file?: ReactNode

  /** gboolean, from Gtk.Picture */
  isolateContents?: boolean

  /** gboolean, from Gtk.Picture */
  keepAspectRatio?: boolean

  /** Gdk.Paintable, from Gtk.Picture */
  paintable?: ReactNode
}

export function Picture({ className, children, alternativeText }: PictureProps) {
  return (
    <div className={cn("outline-offset-[-1px]", "rounded-[12px]", className)}>
      {alternativeText}
      {children}
    </div>
  )
}
